{
  "titre": "Réviser les Trente Glorieuses",
  "objectifGeneral": "Mobiliser les connaissances sur les Trente Glorieuses pour analyser leur héritage",
  "notionsPivots": [
    "la croissance économique",
    "les transformations sociales",
    "la société de consommation",
    "l'État-providence",
    "les limites écologiques",
    "la crise des années 1970"
  ],
  "etapes": [
    {
      "titre": "Repérer les repères chronologiques",
      "objectif": "situer les événements clés des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Chronologie des Trente Glorieuses",
          "objectif": "ordonner les dates et événements marquants",
          "module": "Timeline",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Placez les événements suivants dans l'ordre chronologique sur la frise : début de la société de consommation, création de la Sécurité sociale, premier choc pétrolier, plan Marshall, baby-boom."
        }
      ]
    },
    {
      "titre": "Comprendre les transformations sociales",
      "objectif": "identifier les changements majeurs de la période",
      "cartes": [
        {
          "titre": "Vocabulaire des Trente Glorieuses",
          "objectif": "associer les termes à leur définition",
          "module": "Appariement",
          "palier": "entrainement",
          "duree": 12,
          "consigne": "Associez chaque terme à sa définition en utilisant les cartes proposées : État-providence, société de consommation, baby-boom, plein emploi."
        }
      ]
    },
    {
      "titre": "Analyser les limites du modèle",
      "objectif": "repérer les faiblesses et contradictions des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Les limites des Trente Glorieuses",
          "objectif": "surligner les mots-clés dans un texte",
          "module": "MarkTheWords",
          "palier": "transfert",
          "duree": 10,
          "consigne": "Dans le texte fourni, surlignez tous les termes qui illustrent les limites des Trente Glorieuses : pollution, inégalités, dépendance énergétique, précarité."
        }
      ]
    },
    {
      "titre": "S'entraîner pour vérifier ses acquis",
      "objectif": "valider sa compréhension par un quiz",
      "cartes": [
        {
          "titre": "Quiz de révision",
          "objectif": "répondre à des questions sur les notions clés",
          "module": "QuizSetQCM",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Répondez aux questions suivantes pour vérifier votre maîtrise des notions sur les Trente Glorieuses."
        }
      ]
    }
  ]
}
